use esp_idf_svc::sys::{localtime_r, time_t, tm, tzset};
use log::*;
use sntp_request::SntpRequest;
use std::time::{Duration, Instant};
use time::{Date, Month, OffsetDateTime, PrimitiveDateTime, Time, UtcOffset};

pub struct Clock {
    sntp: SntpRequest,
    last_update: Option<Instant>,
    timestamp: i64,
}

/// IANA name from .env, e.g. "Europe/Prague"
const TIMEZONE: &str = env!("TIMEZONE");
/// POSIX rule for TIMEZONE generated by build.rs, e.g. "CET-1CEST,M3.5.0,M10.5.0/3", evaluated by newlib
const TIMEZONE_POSIX: &str = env!("TIMEZONE_POSIX");

impl Clock {
    pub fn new() -> Self {
        let sntp = SntpRequest::new();
        std::env::set_var("TZ", TIMEZONE_POSIX);
        unsafe { tzset() };
        info!("Timezone: {} ({})", TIMEZONE, TIMEZONE_POSIX);
        Self {
            timestamp: 0,
            sntp,
            last_update: None,
        }
    }

    pub fn sync(&mut self) {
        // sync with remote server
        let result = self.sntp.get_unix_time(); // in seconds

        // update the local timestamp
        // on failure keep the previous reference point, otherwise the clock would jump back
        match result {
            Ok(timestamp) => {
                info!("Sync successful, timestamp: {}", timestamp);
                self.timestamp = timestamp;
                self.last_update = Some(Instant::now());
            }
            Err(e) => {
                error!("Sync failed: {:?}", e);
            }
        }
    }

    /// True if the clock was never synced or the last successful sync is older than `max_age`
    pub fn needs_sync(&self, max_age: Duration) -> bool {
        self.last_update
            .map_or(true, |last_update| last_update.elapsed() >= max_age)
    }

    pub fn get_unix_timestamp(&self) -> Option<i64> {
        self.last_update.map(|last_update| {
            let now = Instant::now();
            let duration = now.duration_since(last_update);

            self.timestamp + duration.as_secs() as i64
        })
    }

    pub fn get_datetime(&self) -> Option<OffsetDateTime> {
        let timestamp = self.get_unix_timestamp()?;
        let datetime = to_local_datetime(timestamp);
        if datetime.is_none() {
            error!("Failed to convert timestamp {} to datetime", timestamp);
        }
        datetime
    }
}

/// Converts a unix timestamp to local time using the TZ rules set in `Clock::new`
fn to_local_datetime(timestamp: i64) -> Option<OffsetDateTime> {
    let mut local: tm = unsafe { std::mem::zeroed() };
    let result = unsafe { localtime_r(&(timestamp as time_t), &mut local) };
    if result.is_null() {
        return None;
    }

    let month = Month::try_from(u8::try_from(local.tm_mon + 1).ok()?).ok()?;
    let date = Date::from_calendar_date(local.tm_year + 1900, month, local.tm_mday as u8).ok()?;
    let time = Time::from_hms(local.tm_hour as u8, local.tm_min as u8, local.tm_sec as u8).ok()?;
    let local = PrimitiveDateTime::new(date, time);

    // newlib's struct tm has no tm_gmtoff, derive the offset from the difference to UTC
    let offset = local.assume_utc().unix_timestamp() - timestamp;
    let offset = UtcOffset::from_whole_seconds(offset as i32).ok()?;
    Some(local.assume_offset(offset))
}
